import React, { useState, useEffect } from "react";
import { getNotes, createNote, deleteNote, updateNote } from "./api";
import "./App.css";

function App() {
  const [notes, setNotes] = useState([]);
  const [newNote, setNewNote] = useState("");
  const [selectedTag, setSelectedTag] = useState("");
  const [tags, setTags] = useState([]);

  useEffect(() => {
    loadNotes();
  }, []);

  const loadNotes = async () => {
    const data = await getNotes();

    // Asegura que cada nota tenga un array de tags válido
    const formattedNotes = data.map(note => ({ ...note, tags: note.tags || [] }));

    setNotes(formattedNotes);

    // Extrae etiquetas sin duplicados
    const allTags = [...new Set(formattedNotes.flatMap(note => note.tags))];
    setTags(allTags);
  };

  const handleAddNote = async () => {
    if (newNote.trim() === "") return;
    await createNote({ content: newNote, archived: false, tags: [] });
    setNewNote("");
    loadNotes();
  };

  const handleDeleteNote = async (id) => {
    await deleteNote(id);
    loadNotes();
  };

  const handleArchiveNote = async (id, archived) => {
    await updateNote(id, { archived: !archived });
    loadNotes();
  };

  const handleAddTag = async (id, tag) => {
    if (!tag.trim()) return; // Evita agregar etiquetas vacías
    const note = notes.find(n => n.id === id);
    if (!note.tags.includes(tag)) {
      await updateNote(id, { tags: [...note.tags, tag] });
      loadNotes();
    }
  };

  const handleRemoveTag = async (id, tag) => {
    const note = notes.find(n => n.id === id);
    const updatedTags = note.tags.filter(t => t !== tag);
    await updateNote(id, { tags: updatedTags });
    loadNotes();
  };

  const filteredNotes = selectedTag
    ? notes.filter(note => note.tags.includes(selectedTag))
    : notes;

  return (
    <div className="container">
      <h1>Notas</h1>

      <input 
        value={newNote} 
        onChange={(e) => setNewNote(e.target.value)} 
        placeholder="Escribe una nota" 
      />
      <button onClick={handleAddNote}>Agregar Nota</button>

      <div className="select-container">
        <h3>Filtrar por etiqueta:</h3>
        <select onChange={(e) => setSelectedTag(e.target.value)} value={selectedTag}>
          <option value="">Todas</option>
          {tags.map(tag => (
            <option key={tag} value={tag}>{tag}</option>
          ))}
        </select>
      </div>

      <h2>Lista de Notas</h2>
      <ul>
        {filteredNotes.map((note) => (
          <li key={note.id}>
            {note.content}
            <button className="archive" onClick={() => handleArchiveNote(note.id, note.archived)}>
              {note.archived ? "Desarchivar" : "Archivar"}
            </button>
            <button className="delete" onClick={() => handleDeleteNote(note.id)}>🗑</button>

            <div>
              <strong>Etiquetas:</strong> {Array.isArray(note.tags) ? note.tags.join(", ") : ""}
              <input
                type="text"
                placeholder="Nueva etiqueta"
                onKeyDown={(e) => {
                  if (e.key === "Enter") {
                    handleAddTag(note.id, e.target.value.trim());
                    e.target.value = "";
                  }
                }}
              />
              {note.tags.map(tag => (
                <button key={tag} onClick={() => handleRemoveTag(note.id, tag)}>❌ {tag}</button>
              ))}
            </div>
          </li>
        ))}
      </ul>
    </div>
  );
}

export default App;
